export function placeOf(code: string): PlaceName | null {
  return PLACES[code.trim().toUpperCase()] ?? null;
}

export function placeCaption(code: string, fallback = code): string {
  const place = placeOf(code);
  if (!place) return fallback;
  return place.country ? place.city + ', ' + place.country : place.city;
}
